    let mut m = Map::new();
    with_line_renderer2d(r, |d| {
        m.insert("width".into(), json!(d.width));
        m.insert(
            "color".into(),
            json!({ "$type": "Color", "value": [d.color.r, d.color.g, d.color.b, d.color.a] }),
        );
        m.insert("loop".into(), json!(d.r#loop));
        m.insert(
            "points".into(),
            Value::Array(
                d.points
                    .iter()
                    .map(|p| json!({ "$type": "Vector2", "value": [p.x, p.y] }))
                    .collect(),
            ),
        );
    });
    m
