/// Removes the generated components of a destroyed object.
pub fn remove_generated_on(object: ObjectId) {
    remove_lights_on(object);
    remove_plane_renderers_on(object);
    remove_mirrors_on(object);
    remove_reflection_probes_on(object);
    remove_world_panels_on(object);
    remove_sprite_renderers_on(object);
    remove_line_renderer2ds_on(object);
    remove_mesh_renderers_on(object);
    remove_skinned_mesh_renderers_on(object);
    remove_lod_groups_on(object);
}

/// Forgets every generated component and asset.
pub fn reset_generated() {
    reset_lights();
    reset_plane_renderers();
    reset_mirrors();
    reset_reflection_probes();
    reset_world_panels();
    reset_sprite_renderers();
    reset_line_renderer2ds();
    reset_mesh_renderers();
    reset_skinned_mesh_renderers();
    reset_lod_groups();
    reset_materials();
    reset_sprites();
}
